def pretty(self, indent=0, debug=False):
    def _format(obj, level):
        prefix = ' ' * (level * 4)
        if isinstance(obj, (list, tuple, set)):
            opening = '[' if isinstance(obj, list) else '(' if isinstance(obj, tuple) else '{'
            closing = ']' if isinstance(obj, list) else ')' if isinstance(obj, tuple) else '}'
            items = []
            for item in obj:
                items.append(_format(item, level+1))
            inner = ',\n'.join(items)
            return f"{opening}\n{inner}\n{prefix}{closing}"
        elif isinstance(obj, dict):
            items = []
            for k, v in obj.items():
                key_str = _format(k, level+1)
                val_str = _format(v, level+1)
                items.append(f"{key_str}: {val_str}")
            inner = ',\n'.join(items)
            return f"{{\n{inner}\n{prefix}}}"
        else:
            if debug:
                return f"{repr(obj)} ({type(obj).__name__})"
            else:
                return repr(obj)
    return _format(self, indent)
