class CommandRegistry:
    def __init__(self) -> None:
        # Example registry structure: {command_name: {argument_name: spec_dict}}
        self._registry: Dict[str, Dict[str, Dict[str, Any]]] = {
            "deploy": {
                "environment": {"type": "string", "required": True, "description": "Target environment"},
                "version": {"type": "string", "required": False, "description": "Version to deploy"},
            },
            "build": {
                "target": {"type": "string", "required": True, "description": "Build target"},
                "optimize": {"type": "bool", "required": False, "description": "Enable optimizations"},
            },
        }

    def get_option_spec(self, command_name: str, argument_name: str) -> Optional[Dict[str, Any]]:
        """
        Gets the specification for the specified option name.

        Parameters
        ----------
        command_name : str
            The name of the command to look up.
        argument_name : str
            The name of the argument within the command.

        Returns
        -------
        Optional[Dict[str, Any]]
            The specification dictionary if found, otherwise None.
        """
        command_options = self._registry.get(command_name)
        if command_options is None:
            return None
        return command_options.get(argument_name)

