import argparse

class MyCLI:
    def __init__(self):
        self.parser = argparse.ArgumentParser(description="My CLI")
        self.subparsers = self.parser.add_subparsers(dest='command')
        self.extend_cli(self.subparsers)

    def extend_cli(self, root_subparsers):
        spec_parser = root_subparsers.add_parser('spec', help='Spec command')
        spec_parser.add_argument('--input', '-i', required=True, help='Input file')
        spec_parser.add_argument('--output', '-o', help='Output file')
        spec_parser.add_argument('--verbose', '-v', action='store_true', help='Verbose output')
        spec_parser.set_defaults(func=self.handle_spec)

    def handle_spec(self, args):
        print(f"Handling spec: input={args.input}, output={args.output}, verbose={args.verbose}")

    def run(self):
        args = self.parser.parse_args()
        if hasattr(args, 'func'):
            args.func(args)
        else:
            self.parser.print_help()

